func (this *Spinner) SetDigits(value int32) {
	this.CheckWidget()
	if value < 0 {
		this.Error(ERROR_INVALID_ARGUMENT)
	}
	var digits int32 = gtk.GTKGtk_spin_button_get_digits(this.Handle)
	if value == digits {
		return
	}
	var hAdjustment int64 = gtk.GTKGtk_spin_button_get_adjustment(this.Handle)
	var adjustment gtk.GtkAdjustment = gtk.GtkAdjustment{}
	this.Gtk_adjustment_get(hAdjustment, &adjustment)
	abs516 := value - digits
	if abs516 < 0 {
		abs516 = -abs516
	}
	var diff int32 = abs516
	var factor int32 = 1
	for i := int32(0); i < diff; i++ {
		factor *= 10
	}
	if digits > value {
		adjustment.Value *= float64(factor)
		adjustment.Upper *= float64(factor)
		adjustment.Lower *= float64(factor)
		adjustment.Step_increment *= float64(factor)
		adjustment.Page_increment *= float64(factor)
		this.climbRate *= float64(factor)
	} else {
		adjustment.Value /= float64(factor)
		adjustment.Upper /= float64(factor)
		adjustment.Lower /= float64(factor)
		adjustment.Step_increment /= float64(factor)
		adjustment.Page_increment /= float64(factor)
		this.climbRate /= float64(factor)
	}
	gtk.GTKGtk_adjustment_configure(hAdjustment, adjustment.Value, adjustment.Lower, adjustment.Upper, adjustment.Step_increment, adjustment.Page_increment, adjustment.Page_size)
	gtk.OSG_signal_handlers_block_matched(this.Handle, gtk.OSG_SIGNAL_MATCH_DATA, 0, 0, int64(0), int64(0), int64(WidgetVALUE_CHANGED))
	gtk.GTKGtk_spin_button_configure(this.Handle, hAdjustment, this.climbRate, value)
	gtk.OSG_signal_handlers_unblock_matched(this.Handle, gtk.OSG_SIGNAL_MATCH_DATA, 0, 0, int64(0), int64(0), int64(WidgetVALUE_CHANGED))
}

func (this *Spinner) SetValues(selection int32, minimum int32, maximum int32, digits int32, increment int32, pageIncrement int32) {
	this.CheckWidget()
	if maximum < minimum {
		return
	}
	if digits < 0 {
		return
	}
	if increment < 1 {
		return
	}
	if pageIncrement < 1 {
		return
	}
	selection = int32(math.Min(float64(int32(math.Max(float64(minimum), float64(selection)))), float64(maximum)))
	var factor float64 = float64(1)
	for i := int32(0); i < digits; i++ {
		factor *= float64(10)
	}
	gtk.OSG_signal_handlers_block_matched(this.Handle, gtk.OSG_SIGNAL_MATCH_DATA, 0, 0, int64(0), int64(0), int64(WidgetVALUE_CHANGED))
	this.climbRate = 1.0 / factor
	var adjustment int64 = gtk.GTKGtk_spin_button_get_adjustment(this.Handle)
	gtk.GTKGtk_spin_button_configure(this.Handle, adjustment, this.climbRate, digits)
	gtk.GTKGtk_spin_button_set_range(this.Handle, float64(minimum)/factor, float64(maximum)/factor)
	gtk.GTKGtk_spin_button_set_increments(this.Handle, float64(increment)/factor, float64(pageIncrement)/factor)
	gtk.GTKGtk_spin_button_set_value(this.Handle, float64(selection)/factor)
	gtk.OSG_signal_handlers_unblock_matched(this.Handle, gtk.OSG_SIGNAL_MATCH_DATA, 0, 0, int64(0), int64(0), int64(WidgetVALUE_CHANGED))
}

